## Modèles de Données Flutter

### DiscoveryFilters

```dart
class DiscoveryFilters {
  final int? ageMin;
  final int? ageMax;
  final int? distanceMaxKm;
  final List<String> genders;
  final List<String> relationshipTypes;
  final bool verifiedOnly;
  final bool onlineOnly;

  DiscoveryFilters({
    this.ageMin,
    this.ageMax,
    this.distanceMaxKm,
    this.genders = const [],
    this.relationshipTypes = const [],
    this.verifiedOnly = false,
    this.onlineOnly = false,
  });

  factory DiscoveryFilters.fromJson(Map<String, dynamic> json) {
    return DiscoveryFilters(
      ageMin: json['age_min'],
      ageMax: json['age_max'],
      distanceMaxKm: json['distance_max_km'],
      genders: List<String>.from(json['genders'] ?? []),
      relationshipTypes: List<String>.from(json['relationship_types'] ?? []),
      verifiedOnly: json['verified_only'] ?? false,
      onlineOnly: json['online_only'] ?? false,
    );
  }

  Map<String, dynamic> toJson() {
    return {
      if (ageMin != null) 'age_min': ageMin,
      if (ageMax != null) 'age_max': ageMax,
      if (distanceMaxKm != null) 'distance_max_km': distanceMaxKm,
      'genders': genders.isEmpty ? ['all'] : genders,
      'relationship_types': relationshipTypes.isEmpty ? ['all'] : relationshipTypes,
      'verified_only': verifiedOnly,
      'online_only': onlineOnly,
    };
  }

  DiscoveryFilters copyWith({
    int? ageMin,
    int? ageMax,
    int? distanceMaxKm,
    List<String>? genders,
    List<String>? relationshipTypes,
    bool? verifiedOnly,
    bool? onlineOnly,
  }) {
    return DiscoveryFilters(
      ageMin: ageMin ?? this.ageMin,
      ageMax: ageMax ?? this.ageMax,
      distanceMaxKm: distanceMaxKm ?? this.distanceMaxKm,
      genders: genders ?? this.genders,
      relationshipTypes: relationshipTypes ?? this.relationshipTypes,
      verifiedOnly: verifiedOnly ?? this.verifiedOnly,
      onlineOnly: onlineOnly ?? this.onlineOnly,
    );
  }
}
```

