### Enum: GenreType

```dart
enum GenreType {
  male('male', 'Homme'),
  female('female', 'Femme'),
  nonBinary('non_binary', 'Non-binaire'),
  transMale('trans_male', 'Homme trans'),
  transFemale('trans_female', 'Femme trans'),
  other('other', 'Autre'),
  preferNotToSay('prefer_not_to_say', 'Préfère ne pas dire');

  final String value;
  final String label;
  const GenreType(this.value, this.label);

  static GenreType fromString(String value) {
    return GenreType.values.firstWhere(
      (e) => e.value == value,
      orElse: () => GenreType.other,
    );
  }
}
```

### Enum: RelationshipType

```dart
enum RelationshipType {
  friendship('friendship', 'Amitié'),
  longTerm('long_term', 'Relation sérieuse'),
  shortTerm('short_term', 'Relation courte'),
  casual('casual', 'Casual');

  final String value;
  final String label;
  const RelationshipType(this.value, this.label);

  static RelationshipType fromString(String value) {
    return RelationshipType.values.firstWhere(
      (e) => e.value == value,
      orElse: () => RelationshipType.friendship,
    );
  }
}
