## Exemples de Code Dart

### Service Complet

```dart
class DiscoveryService {
  final String baseUrl;
  final String token;

  DiscoveryService({
    required this.baseUrl,
    required this.token,
  });

  Map<String, String> get _headers => {
    'Content-Type': 'application/json',
    'Authorization': 'Bearer $token',
  };

  /// Récupère les filtres actuels
  Future<DiscoveryFilters> getFilters() async {
    final response = await http.get(
      Uri.parse('$baseUrl/api/v1/discovery/filters/get'),
      headers: _headers,
    );

    if (response.statusCode == 200) {
      final data = jsonDecode(response.body);
      return DiscoveryFilters.fromJson(data['filters']);
    } else if (response.statusCode == 401) {
      throw AuthException('Token expiré');
    } else {
      throw ServerException('Erreur serveur: ${response.statusCode}');
    }
  }

  /// Met à jour les filtres
  Future<void> updateFilters(DiscoveryFilters filters) async {
    final response = await http.put(
      Uri.parse('$baseUrl/api/v1/discovery/filters'),
      headers: _headers,
      body: jsonEncode(filters.toJson()),
    );

    if (response.statusCode != 200) {
      final data = jsonDecode(response.body);
      throw ValidationException(
        data['details'] ?? {'message': [data['message']]},
      );
    }
  }

  /// Récupère les profils de découverte
  Future<DiscoveryResponse> getDiscoveryProfiles({
    int page = 1,
    int pageSize = 10,
  }) async {
    final response = await http.get(
      Uri.parse(
        '$baseUrl/api/v1/discovery/profiles?page=$page&page_size=$pageSize',
      ),
      headers: _headers,
    );

    if (response.statusCode == 200) {
      final data = jsonDecode(response.body);
      return DiscoveryResponse.fromJson(data);
    } else {
      throw ServerException('Erreur serveur: ${response.statusCode}');
    }
  }

  /// Like un profil
  Future<InteractionResult> likeProfile(String targetUserId) async {
    final response = await http.post(
      Uri.parse('$baseUrl/api/v1/discovery/interactions/like'),
      headers: _headers,
      body: jsonEncode({'target_user_id': targetUserId}),
    );

    final data = jsonDecode(response.body);
    return InteractionResult(
      success: data['status'] == 'success',
      isMatch: data['is_match'] ?? false,
      message: data['message'],
    );
  }

  /// Dislike un profil
  Future<void> dislikeProfile(String targetUserId) async {
    await http.post(
      Uri.parse('$baseUrl/api/v1/discovery/interactions/dislike'),
      headers: _headers,
      body: jsonEncode({'target_user_id': targetUserId}),
    );
  }

  /// Super-like un profil (Premium)
  Future<InteractionResult> superlikeProfile(String targetUserId) async {
    final response = await http.post(
      Uri.parse('$baseUrl/api/v1/discovery/interactions/superlike'),
      headers: _headers,
      body: jsonEncode({'target_user_id': targetUserId}),
    );

    final data = jsonDecode(response.body);
    return InteractionResult(
      success: data['status'] == 'success',
      isMatch: data['is_match'] ?? false,
      message: data['message'],
    );
  }
}

class DiscoveryResponse {
  final int count;
  final String? next;
  final String? previous;
  final List<DiscoveryProfile> results;

  DiscoveryResponse({
    required this.count,
    this.next,
    this.previous,
    required this.results,
  });

  factory DiscoveryResponse.fromJson(Map<String, dynamic> json) {
    return DiscoveryResponse(
      count: json['count'],
      next: json['next'],
      previous: json['previous'],
      results: (json['results'] as List)
          .map((p) => DiscoveryProfile.fromJson(p))
          .toList(),
    );
  }

  bool get hasMore => next != null;
}

class InteractionResult {
  final bool success;
  final bool isMatch;
  final String? message;

  InteractionResult({
    required this.success,
    required this.isMatch,
    this.message,
  });
}

class AuthException implements Exception {
  final String message;
  AuthException(this.message);
}

class ServerException implements Exception {
  final String message;
  ServerException(this.message);
}

class ValidationException implements Exception {
  final Map<String, List<String>> errors;
  ValidationException(this.errors);
}
```

